","export class AnalyticsService {
 constructor() {
 this.baseUrl = '/api/x_780831_analytics/analytics_now';
 }

 async processQuery(query) {
 try {
 console.log('Analytics Service: Processing query:', query);

 const requestBody = {
 data: { query }
 };

 console.log('Analytics Service: Request body:', JSON.stringify(requestBody));

 const response = await fetch(`${this.baseUrl}/query`, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(requestBody)
 });

 console.log('Analytics Service: Response status:', response.status);

 if (!response.ok) {
 const errorText = await response.text();
 console.error('Analytics Service: Error response:', errorText);

 let errorData;
 try {
 errorData = JSON.parse(errorText);
 } catch (e) {
 errorData = { error: errorText };
 }

 throw new Error(errorData?.error || `HTTP ${response.status}: ${response.statusText}`);
 }

 const result = await response.json();
 console.log('Analytics Service: Success response:', result);

 if (!result.success && result.error) {
 throw new Error(result.error);
 }

 return result;
 } catch (error) {
 console.error('Analytics service error:', error);
 throw new Error(error.message || 'Failed to process query');
 }
 }

 async getQueryHistory(limit = 10) {
 try {
 const response = await fetch(`/api/now/table/x_780831_analytics_query?sysparm_limit=${limit}&sysparm_order_by=sys_created_on&sysparm_order_direction=desc&sysparm_display_value=all`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 throw new Error(`Failed to fetch query history: ${response.statusText}`);
 }

 const data = await response.json();
 return data.result || [];
 } catch (error) {
 console.error('Failed to get query history:', error);
 return [];
 }
 }

 async getQueryResults(queryId) {
 try {
 const response = await fetch(`/api/now/table/x_780831_analytics_result?sysparm_query=query=${queryId}&sysparm_order_by=result_index&sysparm_display_value=all`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 throw new Error(`Failed to fetch query results: ${response.statusText}`);
 }

 const data = await response.json();
 return data.result || [];
 } catch (error) {
 console.error('Failed to get query results:', error);
 return [];
 }
 }
