import './QueryHistory.css';

export default function QueryHistory({ history, onSelect }) {
 if (!history || history.length === 0) {
 return (
 <div className="history-container">
 <h3>Query History</h3>
 <div className="empty-history">
 <div className="empty-icon">🕒</div>
 <p>Your recent queries will appear here</p>
 </div>
 </div>
 );
 }

 const formatTime = (timestamp) => {
 const now = new Date();
 const diff = now - new Date(timestamp);
 const minutes = Math.floor(diff / 60000);

 if (minutes < 1) return 'Just now';
 if (minutes < 60) return `${minutes}m ago`;

 const hours = Math.floor(minutes / 60);
 if (hours < 24) return `${hours}h ago`;

 const days = Math.floor(hours / 24);
 return `${days}d ago`;
 };

 const truncateQuery = (query, maxLength = 60) => {
 if (query.length <= maxLength) return query;
 return query.substring(0, maxLength) + '...';
 };

 return (
 <div className="history-container">
 <h3>Query History</h3>
 <div className="history-list">
 {history.map((item) => (
 <div
 key={item.id}
 className={`history-item ${item.success ? 'success' : 'error'}`}
 onClick={() => onSelect(item)}
 >
 <div className="history-status">
 <span className={`status-indicator ${item.success ? 'success' : 'error'}`}>
 {item.success ? '✓' : '✗'}
 </span>
 </div>

 <div className="history-content">
 <div className="history-query" title={item.query}>
 {truncateQuery(item.query)}
 </div>

 <div className="history-meta">
 <span className="history-time">{formatTime(item.timestamp)}</span>
 {item.success && (
 <>
 <span className="history-count">{item.resultCount} results</span>
 <span className="history-timing">{item.executionTime}ms</span>
 </>
 )}
 </div>
 </div>

 <div className="history-actions">
 <button 
 className="replay-button"
 onClick={(e) => {
 e.stopPropagation();
 onSelect(item);
 }}
 title="Replay query"
 >
 🔄
 </button>
 </div>
 </div>
 ))}
 </div>

 <div className="history-footer">
 <small>Click any query to replay it</small>
 </div>
 </div>
 );
}","import React from 'react';
import './ResultsDisplay.css';

export default function ResultsDisplay({ result, isLoading }) {
 if (isLoading) {
 return (
 <div className="results-container">
 <div className="results-header">
 <h2>Processing Query</h2>
 </div>
 <div className="loading-content">
 <div className="loading-spinner large"></div>
 <p>Analyzing your query with AI and fetching results...</p>
 </div>
 </div>
 );
 }

 if (!result) {
 return (
 <div className="results-container">
 <div className="results-header">
 <h2>Results</h2>
 </div>
 <div className="empty-state">
 <div className="empty-icon">🤖</div>
 <p>Submit a natural language query to see AI-powered results here</p>
 <small>Example: "Show incident trends over last 3 months"</small>
 </div>
 </div>
 );
 }

 if (!result.success) {
 return (
 <div className="results-container">
 <div className="results-header">
 <h2>Query Error</h2>
 </div>
 <div className="error-content">
 <div className="error-icon">⚠️</div>
 <p>{result.error || 'An error occurred processing your query'}</p>
 {result.debug_info && (
 <div className="debug-info">
 <details>
 <summary>Debug Information</summary>
 <pre>{JSON.stringify(result.debug_info, null, 2)}</pre>
 </details>
 </div>
 )}
 </div>
 </div>
 );
 }

 const extractFieldValue = (field) => {
 return typeof field === 'object' ? field.display_value || field.value : field;
 };

 const renderVisualization = () => {
 const visualization = result.query_result?.visualization || 'table';

 if (visualization === 'table' || !result.results || result.results.length === 0) {
 return renderTable();
 }

 // For now, show table for all visualizations
 // In a full implementation, you'd add chart libraries here
 return (
 <div className="visualization-container">
 <div className="viz-note">
 📈 Suggested visualization: <strong>{visualization.charAt(0).toUpperCase() + visualization.slice(1)} Chart</strong>
 {visualization === 'line' && <span> - Perfect for trend analysis!</span>}
 {visualization === 'bar' && <span> - Great for comparisons!</span>}
 </div>
 {renderTable()}
 </div>
 );
 };

 const renderTable = () => {
 if (!result.results || result.results.length === 0) {
 return (
 <div className="no-results">
 <p>No results found for your query</p>
 <small>Try adjusting your time range or search criteria</small>
 </div>
 );
 }

 // Get all unique keys from results
 const allKeys = [...new Set(result.results.flatMap(Object.keys))];
 const displayKeys = allKeys.filter(key => !key.endsWith('_raw') && key !== 'sys_id');

 return (
 <div className="table-container">
 <table className="results-table">
 <thead>
 <tr>
 {displayKeys.map(key => (
 <th key={key}>{formatFieldName(key)}</th>
 ))}
 </tr>
 </thead>
 <tbody>
 {result.results.slice(0, 50).map((row, index) => (
 <tr key={index}>
 {displayKeys.map(key => (
 <td key={key}>
 {extractFieldValue(row[key]) || '-'}
 </td>
 ))}
 </tr>
 ))}
 </tbody>
 </table>
 {result.results.length > 50 && (
 <div className="table-footer">
 Showing first 50 of {result.result_count} records
 </div>
 )}
 </div>
 );
 };

 const formatFieldName = (fieldName) => {
 return fieldName
 .split('_')
 .map(word => word.charAt(0).toUpperCase() + word.slice(1))
 .join(' ');
 };

 const getProcessingMethodIcon = () => {
 return result.processing_method === 'AI' ? '🤖' : '📝';
 };

 const getProcessingMethodColor = () => {
 return result.processing_method === 'AI' ? '#4CAF50' : '#FF9800';
 };

 return (
 <div className="results-container">
 <div className="results-header">
 <h2>Analytics Results</h2>
 <div className="results-meta">
 <span className="result-count">{result.result_count} records</span>
 <span className="execution-time">{result.execution_time}ms</span>
 {result.query_result?.table && (
 <span className="target-table">📊 {result.query_result.table}</span>
 )}
 {result.processing_method && (
 <span 
 className="processing-method" 
 style={{ color: getProcessingMethodColor() }}
 title={result.processing_method === 'AI' ? 'Processed using AI' : 'Processed using rule-based logic'}
 >
 {getProcessingMethodIcon()} {result.processing_method}
 </span>
 )}
 </div>
 </div>

 <div className="results-content">
 {result.query_result?.description && (
 <div className="query-description">
 <strong>📋 Query Analysis:</strong> {result.query_result.description}
 </div>
 )}

 {result.query_result?.encoded_query && (
 <div className="encoded-query">
 <details>
 <summary>🔍 ServiceNow Query Generated</summary>
 <code>{result.query_result.encoded_query || 'No filters applied'}</code>
 </details>
 </div>
 )}

 {result.debug_info && result.debug_info.ai_configured && (
 <div className="ai-status">
 ✅ AI-powered processing active
 </div>
 )}

 {renderVisualization()}

 {result.query_result?.aggregates && result.query_result.aggregates.length > 0 && (
 <div className="aggregation-info">
 <strong>📈 Aggregations detected:</strong> {result.query_result.aggregates.join(', ')}
 </div>
 )}
 </div>
 </div>
 );
}",".query-input-container {
