);","import React, { useState, useMemo } from 'react';
import { AnalyticsService } from './services/AnalyticsService.js';
import QueryInput from './components/QueryInput.jsx';
import QueryHistory from './components/QueryHistory.jsx';
import ResultsDisplay from './components/ResultsDisplay.jsx';
import './app.css';

export default function App() {
 const service = useMemo(() => new AnalyticsService(), []);
 const [currentResult, setCurrentResult] = useState(null);
 const [isLoading, setIsLoading] = useState(false);
 const [queryHistory, setQueryHistory] = useState([]);

 const handleQuerySubmit = async (query) => {
 setIsLoading(true);
 try {
 const result = await service.processQuery(query);
 setCurrentResult(result);

 // Add to history
 const historyItem = {
 id: result.query_id,
 query: query,
 timestamp: new Date(),
 success: result.success,
 resultCount: result.result_count,
 executionTime: result.execution_time
 };

 setQueryHistory(prev => [historyItem, ...prev.slice(0, 9)]); // Keep last 10
 } catch (error) {
 console.error('Query error:', error);
 setCurrentResult({
 success: false,
 error: error.message,
 results: []
 });
 } finally {
 setIsLoading(false);
 }
 };

 const handleHistorySelect = (historyItem) => {
 // Re-run the query or load cached results
 handleQuerySubmit(historyItem.query);
 };

 return (
 <div className="analytics-app">
 <header className="app-header">
 <h1>🤖 AN - Analytics Now</h1>
 <p>AI-powered reporting agent for ServiceNow data</p>
 </header>

 <main className="app-main">
 <div className="query-section">
 <QueryInput 
 onSubmit={handleQuerySubmit} 
 isLoading={isLoading}
 />
 </div>

 <div className="content-grid">
 <div className="results-section">
 <ResultsDisplay 
 result={currentResult} 
 isLoading={isLoading}
 />
 </div>

 <div className="history-section">
 <QueryHistory 
 history={queryHistory}
 onSelect={handleHistorySelect}
 />
 </div>
 </div>
 </main>
 </div>
 );
